import{_ as e,c as o,o as a,b0 as r}from"./chunks/framework.C5ev1SXp.js";const d="/scm-docs/assets/image-20230507131203330.pVOpjcZb.png",s="/scm-docs/assets/image-20220903160151362.BmAdMNnO.png",n="/scm-docs/assets/image-20230507131219435.BqNLcX6V.png",c="/scm-docs/assets/image-20230507131440446.DffOpY8O.png",p="/scm-docs/assets/image-20230507131453955.BFL3Oia_.png",i="/scm-docs/assets/image-20220903162111744.CDK_fdj3.png",l="/scm-docs/assets/image-20230507131505419.BLdhcP1k.png",b=JSON.parse('{"title":"LV020-AT24C02读写时序分析","description":null,"frontmatter":{"title":"LV020-AT24C02读写时序分析","date":"2025-09-22T07:40:58.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/communication/i2c/126b09043fca31869028172d","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-09-22T07:40:58.792Z","fulluuid":"69028172daa144dcbab34851329c3348","useduuid":"69028172d"}},"headers":[],"relativePath":"sdoc/communication/i2c/126b09043fca31869028172d.md","filePath":"sdoc/60-通信专题/01-I2C协议/LV020-AT24C02读写时序分析.md","lastUpdated":1793515252000}'),u={name:"sdoc/communication/i2c/126b09043fca31869028172d.md"};function h(q,t,m,A,g,C){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="lv020-at24c02读写时序分析" tabindex="-1">LV020-AT24C02读写时序分析 <a class="header-anchor" href="#lv020-at24c02读写时序分析" aria-label="Permalink to &quot;LV020-AT24C02读写时序分析&quot;">​</a></h1><p>AT24C02 是一个 256 字节（2Kbit）的 EEPROM，它使用的通信接口就是标准 I2C。与 <a href="/scm-docs/sdoc/communication/i2c/126d67bc563d22c0aee96b8e.html">LV010-I2C时序与软件模拟</a> 里讲到的&quot;裸&quot;总线收发相比，它多了一层<strong>字地址</strong>的概念，是分析实际器件读写时序的最好例子。这一篇就结合它的芯片手册（<a href="https://ww1.microchip.com/downloads/en/DeviceDoc/doc5126.pdf" target="_blank" rel="noreferrer">AT24C02B 数据手册</a>），把字节写、页写、当前地址读、随机读、顺序读共 5 种读写时序逐一过一遍。</p><h2 id="一、分析前的准备-设备地址与字地址" tabindex="-1">一、分析前的准备：设备地址与字地址 <a class="header-anchor" href="#一、分析前的准备-设备地址与字地址" aria-label="Permalink to &quot;一、分析前的准备：设备地址与字地址&quot;">​</a></h2><h3 id="_1-设备地址" tabindex="-1">1. 设备地址 <a class="header-anchor" href="#_1-设备地址" aria-label="Permalink to &quot;1. 设备地址&quot;">​</a></h3><p>I2C 总线靠设备地址区分不同器件。AT24C02 的 <strong>7 位设备地址</strong>由高 4 位固定值 <code>1010</code> 和随后 3 位地址引脚 A2、A1、A0 的电平组成；发送时再在末尾拼接 1 位读写方向位 R/W，形成 8 位地址字节——R/W 为 0 表示写、为 1 表示读。以 A2~A0 全部接地为例：</p><p>（1）写操作时发送的地址字节是 <code>1010 0000</code> = 0xA0；</p><p>（2）读操作时发送的地址字节是 <code>1010 0001</code> = 0xA1。</p><p>引脚接法与容量分页的更多细节，可以看外设篇的笔记 <a href="/scm-docs/sdoc/peripheral/i2c/126b09344d8f021f00cacd6c.html">LV010-AT24C02简介</a>。</p><h3 id="_2-字地址-word-address" tabindex="-1">2. 字地址（Word Address） <a class="header-anchor" href="#_2-字地址-word-address" aria-label="Permalink to &quot;2. 字地址（Word Address）&quot;">​</a></h3><p>I2C 协议本身没有&quot;存储地址&quot;的概念，总线上传输的都是普普通通的数据字节，是器件自己约定了这些字节的含义。AT24C02 内部有 256 个存储单元，每个单元的编号（0x00 ~ 0xFF）就是<strong>字地址</strong>。它的约定是：</p><p>（1）写操作中，设备地址之后发送的<strong>第一个数据字节</strong>总是被解释为字地址，之后的字节才是真正写入的数据；</p><p>（2）读操作可以不带字地址（顺着内部地址计数器读），也可以先用一段&quot;假写&quot;把字地址装进计数器再读。</p><p>理解了&quot;同一个字节，按其在时序中的位置被解释为地址或数据&quot;，下面 5 种时序就都顺理成章了。</p><h2 id="二、写时序" tabindex="-1">二、写时序 <a class="header-anchor" href="#二、写时序" aria-label="Permalink to &quot;二、写时序&quot;">​</a></h2><h3 id="_1-字节写-byte-write" tabindex="-1">1. 字节写（Byte Write） <a class="header-anchor" href="#_1-字节写-byte-write" aria-label="Permalink to &quot;1. 字节写（Byte Write）&quot;">​</a></h3><p>字节写是向单个地址写入一个字节，时序图如下：</p><img src="'+d+'" alt="AT24C02 字节写时序" style="zoom:67%;"><p>同一时序的标注版（红色数字依次标出起始、地址位、读写位、应答、字地址、数据、停止等节点）：</p><img src="'+s+'" alt="AT24C02 字节写时序标注版" style="zoom:80%;"><p>（1）主机产生起始信号 S；</p><p>（2）主机发送设备地址字节 0xA0，R/W 位为 0 表示写；</p><p>（3）地址匹配的从机在第 9 个时钟把 SDA 拉低，回 ACK；</p><p>（4）主机发送第二个字节——字地址，指定要写入的存储单元；</p><p>（5）从机再次回 ACK；</p><p>（6）主机发送要写入的数据字节，8 位、高位在前；</p><p>（7）从机回 ACK；</p><p>（8）主机产生停止信号 P，传输结束。</p><p>【<strong>注意</strong>】字节写全程只有一次起始信号，没有重复起始信号，方向也始终是主机到从机——它就是 LV010 里&quot;主机写时序&quot;套上&quot;第一个数据字节是字地址&quot;的约定而已。</p><p>停止信号之后，器件进入内部写周期（手册记为 tWR，最大 5 ms），把收到的数据写入非易失存储阵列，期间器件不响应总线。主机若想紧接着再次访问，可以使用&quot;应答轮询&quot;（Acknowledge Polling）：反复发起设备地址并检测是否收到 ACK，一旦收到即说明写周期结束。这种&quot;每写一段就要等一次写周期&quot;的特性，正是页写要优化的对象。</p><h3 id="_2-页写-page-write" tabindex="-1">2. 页写（Page Write） <a class="header-anchor" href="#_2-页写-page-write" aria-label="Permalink to &quot;2. 页写（Page Write）&quot;">​</a></h3><p>页写用一个字地址连续写入最多一页（本文手册对应的 AT24C02B 为 8 字节，其他版本以各自手册为准）的数据：</p><img src="'+n+'" alt="AT24C02 页写时序" style="zoom:50%;"><p>（1）前半段与字节写完全相同：起始信号 → 设备地址 0xA0 → ACK → 字地址 n → ACK；</p><p>（2）主机不再只发一个数据，而是连续发送 DATA(n)、DATA(n+1)、……、DATA(n+x)，每个字节之后从机各回一个 ACK，内部地址计数器随之自动 +1；</p><p>（3）数据发送完毕，主机产生停止信号 P，器件开始内部写周期。</p><p>三个要点：</p><p>（1）AT24C02B 每页 8 字节，一次页写最多连续写 8 个字节，但不要求写满整页，只写一两个字节也允许（部分页写入）；</p><p>（2）页写期间地址计数器只有<strong>低 3 位</strong>自增，高 5 位（页号）不变。如果一次写入超过 8 个字节、或从页中间写到页尾还继续，计数器会<strong>回卷到本页页首</strong>，把本页开头刚写的数据覆盖掉——这是实际使用中最经典的坑；</p><p>（3）页写把&quot;每个字节一次完整时序 + 一次写周期等待&quot;压缩成&quot;一次时序 + 一次写周期&quot;，无论通信效率还是写入速度都高得多。</p><p>对比字节写：字节写适合修改零星几个单元，页写适合成块写入，两者不是谁取代谁。</p><h2 id="三、读时序" tabindex="-1">三、读时序 <a class="header-anchor" href="#三、读时序" aria-label="Permalink to &quot;三、读时序&quot;">​</a></h2><h3 id="_1-当前地址读-current-address-read" tabindex="-1">1. 当前地址读（Current Address Read） <a class="header-anchor" href="#_1-当前地址读-current-address-read" aria-label="Permalink to &quot;1. 当前地址读（Current Address Read）&quot;">​</a></h3><p>先认识一个关键角色——<strong>内部地址计数器</strong>。AT24C02 会记住上一次读或写操作所访问的字地址，操作完成后把它 +1 保存；只要芯片保持供电，这个地址在不同操作之间一直有效。当前地址读就是&quot;顺着这个计数器读&quot;，因此全程不需要发送字地址：</p><img src="'+c+'" alt="AT24C02 当前地址读时序" style="zoom:50%;"><p>（1）主机产生起始信号 S；</p><p>（2）主机发送设备地址字节 0xA1，R/W 位为 1 表示读；</p><p>（3）从机回 ACK；</p><p>（4）从机把地址计数器指向单元的内容逐位送上 SDA，8 位、高位在前；</p><p>（5）主机只想要这一个字节，接收完不拉低 SDA，回 NACK；</p><p>（6）主机产生停止信号 P，读操作结束。</p><p>它适合&quot;接着上一次访问的位置继续读一个字节&quot;；要读任意指定单元，则需要下面的随机读。</p><h3 id="_2-随机读-random-read" tabindex="-1">2. 随机读（Random Read） <a class="header-anchor" href="#_2-随机读-random-read" aria-label="Permalink to &quot;2. 随机读（Random Read）&quot;">​</a></h3><p>想读任意指定单元，就得先把字地址告诉器件，但读时序里器件不会再接收&quot;数据&quot;。所以要先做一段<strong>假写</strong>（Dummy Write）把字地址装进地址计数器，再用<strong>重复起始信号 Sr</strong> 把方向切换到读——这正是 <a href="/scm-docs/sdoc/communication/i2c/126d67bc563d22c0aee96b8e.html">LV010-I2C时序与软件模拟</a> 中&quot;复合通信&quot;时序的实际应用：</p><img src="'+p+'" alt="AT24C02 随机读时序" style="zoom:50%;"><p>同一时序的标注版（下半部分标出了&quot;假写&quot;覆盖的范围，底色区分设备地址、字地址与数据段）：</p><img src="'+i+'" alt="AT24C02 随机读时序标注版" style="zoom:80%;"><p>（1）主机产生起始信号 S；</p><p>（2）主机发送设备地址字节 0xA0（写方向）；</p><p>（3）从机回 ACK；</p><p>（4）主机发送字地址 n，从机回 ACK——到这一步为止就是一段&quot;假写&quot;：后面没有数据字节、也不会产生停止信号，什么都没写进去，只是把 n 装进了地址计数器；</p><p>（5）主机不发停止信号，而是再次产生起始信号（重复起始 Sr），保住总线控制权；</p><p>（6）主机重新发送设备地址字节 0xA1（读方向）；</p><p>（7）从机回 ACK；</p><p>（8）从机从字地址 n 开始送出数据 DATA n；</p><p>（9）主机只读这一个字节，回 NACK；</p><p>（10）主机产生停止信号 P，读操作结束。</p><p>【<strong>注意</strong>】这里使用重复起始信号 Sr，可在不释放总线的情况下切换方向；若改成&quot;停止 + 重新开始&quot;，总线会在两段之间释放，多主机环境下其他主机可能趁机占用总线。不能把这个需求扩展为&quot;所有 I2C 方向切换都必须使用 Sr&quot;，具体事务格式仍应以器件手册为准（见 LV010-I2C时序与软件模拟 的复合通信一节）。</p><h3 id="_3-顺序读-sequential-read" tabindex="-1">3. 顺序读（Sequential Read） <a class="header-anchor" href="#_3-顺序读-sequential-read" aria-label="Permalink to &quot;3. 顺序读（Sequential Read）&quot;">​</a></h3><h4 id="_3-1-时序过程" tabindex="-1">3.1 时序过程 <a class="header-anchor" href="#_3-1-时序过程" aria-label="Permalink to &quot;3.1 时序过程&quot;">​</a></h4><p>顺序读是另外两种读的&quot;连续版&quot;：以当前地址读或随机读作为开头，区别只在数据阶段——主机每收到一个字节后<strong>不回 NACK，而是回 ACK</strong>，从机就会把地址计数器 +1，继续送下一个字节：</p><img src="'+l+'" alt="AT24C02 顺序读时序" style="zoom:50%;"><p>（1）开头与随机读（或当前地址读）完全相同，主机收到第一个数据 DATA n；</p><p>（2）主机回 ACK，从机继续发送 DATA n+1、DATA n+2、……、DATA n+x；</p><p>（3）主机读够了，对最后一个字节回 NACK，表示&quot;到此为止&quot;；</p><p>（4）主机产生停止信号 P，读操作结束。</p><p>结束方式固定为 NACK + 停止信号：数据阶段的 ACK 和结束时的 NACK 是同一位的两种取值，前者是&quot;接着送&quot;，后者是&quot;到此为止&quot;，随后主机释放总线。</p><h4 id="_3-2-地址自增与回卷" tabindex="-1">3.2 地址自增与回卷 <a class="header-anchor" href="#_3-2-地址自增与回卷" aria-label="Permalink to &quot;3.2 地址自增与回卷&quot;">​</a></h4><p>顺序读能一直读下去，靠的是从机内部的地址计数器在<strong>整个 256 字节空间</strong>内自增，读到最后一个单元 0xFF 后回卷到 0x00 继续读——对比页写的&quot;跨页覆盖&quot;，读操作可以无限跨页连续。</p><p>这条不是从时序图推出来的，手册写得很直接（<a href="https://ww1.microchip.com/downloads/en/DeviceDoc/doc5126.pdf" target="_blank" rel="noreferrer">AT24C02B 数据手册 5126H–SEEPR–8/07</a>，第 10 页 <code>8. Read Operations</code> → <code>SEQUENTIAL READ</code>，对应波形见第 12 页 <code>Figure 8-6. Sequential Read</code>）：</p><blockquote><p>After the microcontroller receives a data word, it responds with an acknowledge. <strong>As long as the EEPROM receives an acknowledge, it will continue to increment the data word address</strong> and serially clock out sequential data words. When the memory address limit is reached, the data word address will &quot;roll over&quot; and the sequential read will continue.</p></blockquote><p>译：主机每收到一个数据字就回一个 ACK；<strong>只要 EEPROM 收到 ACK，它就把数据字地址加一</strong>，继续串行送出下一个数据字；地址到顶后回卷，连续读照常进行。</p><p>注意手册把两种回卷分开写，别混用：<strong>读</strong>是 &quot;the last byte of the last memory page to the first byte of the first page&quot;，即 <code>0xFF</code> 之后回到 <code>0x00</code>，整片循环；<strong>写</strong>才是 &quot;the last byte of the current page to the first byte of the same page&quot;，即 <code>0x17</code> 之后回到 <code>0x10</code>，只在 8 字节页内循环。所以&quot;页&quot;只是写的边界，不约束读。</p><h2 id="四、五种时序小结" tabindex="-1">四、五种时序小结 <a class="header-anchor" href="#四、五种时序小结" aria-label="Permalink to &quot;四、五种时序小结&quot;">​</a></h2><h3 id="_1-对比一览" tabindex="-1">1. 对比一览 <a class="header-anchor" href="#_1-对比一览" aria-label="Permalink to &quot;1. 对比一览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时序</th><th>是否发送字地址</th><th>是否用重复起始 Sr</th><th>数据阶段应答方</th><th>结束方式</th></tr></thead><tbody><tr><td>字节写</td><td>是</td><td>否</td><td>从机回 ACK</td><td>主机发 P</td></tr><tr><td>页写</td><td>是（1 个）</td><td>否</td><td>从机逐字节回 ACK</td><td>主机发 P</td></tr><tr><td>当前地址读</td><td>否</td><td>否</td><td>主机回 NACK</td><td>NACK + P</td></tr><tr><td>随机读</td><td>是（假写装入）</td><td>是</td><td>主机回 NACK</td><td>NACK + P</td></tr><tr><td>顺序读</td><td>视起点而定</td><td>视起点而定</td><td>主机逐字节回 ACK，末字节回 NACK</td><td>NACK + P</td></tr></tbody></table><h3 id="_2-回到协议本身" tabindex="-1">2. 回到协议本身 <a class="header-anchor" href="#_2-回到协议本身" aria-label="Permalink to &quot;2. 回到协议本身&quot;">​</a></h3><p>把 5 张时序图放在一起看，AT24C02 其实只用了 I2C 协议的三个基础机制：</p><p>（1）<strong>地址与数据的复用</strong>：写操作的第一个数据字节永远是字地址，之后才是数据——&quot;命令、地址、数据的本质都是数据&quot;，含义由其在时序中的位置决定；这一点在硬件 I2C 库函数里体现为&quot;子地址&quot;参数（如 <code>HAL_I2C_Mem_Write()</code> 的 <code>MemAddress</code>）；</p><p>（2）<strong>重复起始信号 Sr</strong>：本文这种不释放总线的&quot;先写后读&quot;复合传输靠它完成方向切换，随机读就是最典型的例子；</p><p>（3）<strong>ACK / NACK 的方向语义</strong>：写时由从机应答，表示&quot;收到了&quot;；读时由主机应答——ACK 表示&quot;还要继续&quot;，NACK 表示&quot;读完了&quot;。</p><p>在 STM32 上用硬件 I2C 和 HAL 库实际读写这片 EEPROM 的完整代码（CubeMX 配置、字节写、页写与分页算法、测试程序），见外设篇的笔记 <a href="/scm-docs/sdoc/peripheral/i2c/126b09344f37186302faabd7.html">LV015-AT24C02使用实例</a>。</p>',91)])])}const f=e(u,[["render",h]]);export{b as __pageData,f as default};
